// groupPath renders a group id into its admin route path.
func groupPath(id int64) string {
	return "/api/v1/admin/groups/" + strconv.FormatInt(id, 10)
}

// decodeAdminGroup pulls an adminGroup out of a 2xx response.
func decodeAdminGroup(t *testing.T, resp *http.Response) adminGroup {
	t.Helper()
	var ag adminGroup
	if err := json.NewDecoder(resp.Body).Decode(&ag); err != nil {
		t.Fatalf("decode adminGroup: %v", err)
	}
	return ag
}

