// createGroupViaAPI creates a group through the endpoint itself (the common
// seed — every later request then rides the same rows the surface wrote).
func createGroupViaAPI(t *testing.T, h http.Handler, name string) adminGroup {
	t.Helper()
	resp := doRequest(t, h, http.MethodPost, "/api/v1/admin/groups",
		`{"name":`+strconv.Quote(name)+`}`, adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusCreated {
		t.Fatalf("create group %q = %d, want 201", name, resp.StatusCode)
	}
	return decodeAdminGroup(t, resp)
}

// addCollectionViaAPI adds a library to a group at a position through the
// endpoint (204 expected).
func addCollectionViaAPI(t *testing.T, h http.Handler, groupID, libraryID, position int64) {
	t.Helper()
	resp := doRequest(t, h, http.MethodPost, groupPath(groupID)+"/collections",
		`{"library_id":`+strconv.FormatInt(libraryID, 10)+`,"position":`+strconv.FormatInt(position, 10)+`}`,
		adminToken)
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		t.Fatalf("add collection %d to group %d = %d, want 204", libraryID, groupID, resp.StatusCode)
	}
}

